function mapEmbeddingKind(kind:string):ContextSourceType{switch(kind){case"chapter_body_version":return"body_version";case"story_event_timing":return"story_time";case"story_event_relation":return"story_event_relation";case"research_document_version":return"research_document_version";case"research_record_version":return"research_version";case"research_reference_pack_version":return"research_pack_version";case"prompt_component":return"prompt_component";case"card_version":case"canonical_fact":case"state_change":case"knowledge_state_change":case"planning_version":return kind;default:throw new NewDesignError(`检索轨迹包含尚未开放给上下文装配的来源类型“${kind}”。`,422);}}
function dependencyKind(sourceType:ContextSourceType):string{switch(sourceType){case"body_version":return"chapter_body_version";case"story_time":return"story_event_timing";case"research_version":return"research_record_version";case"research_pack_version":return"research_reference_pack_version";case"prompt_component":return"card_version";default:return sourceType;}}

async function insertPreviewDependency(client:PoolClient,sourceKind:string,stableId:string,versionId:string,previewId:string,strength:"hard"|"soft"="soft"){await client.query("SELECT new_design.add_registered_dependency($1,$2,$3,'context_preview',$4,$4,'context_included',$5,'context_build',$4)",[sourceKind,stableId,versionId,previewId,strength]);}
